73	     * when {@code namesakeCount} is 0, plus 2 for a household of 3 or more owners, plus 3 when
74	     * tenure exceeds 365 days. Because a newly created owner has zero tenure, the tenure points
75	     * are only earned on later reads.
76	     */
77	    protected Integer membershipPoints(Owner owner) {
78	        int points = 0;
79	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
80	            points += 2;
81	        }
82	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount().intValue() == 0) {
83	            points += 1;
84	        }
85	        if (householdSize(owner) >= 3) {
86	            points += 2;
87	        }
