94	    }
95	
96	    /**
97	     * Map {@link #membershipPoints(Owner)} to a membership level from 1 to 4: level 1 for 0-1
98	     * points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more.
99	     */
100	    protected Integer membershipLevel(Owner owner) {
101	        int points = membershipPoints(owner);
102	        if (points <= 1) {
103	            return 1;
104	        }
105	        if (points <= 3) {
106	            return 2;
107	        }
108	        if (points <= 5) {
109	            return 3;
110	        }
111	        return 4;
112	    }
113	
114	    /**
115	     * The number of owners in this owner's household, identified by the shared {@code householdId}
116	     * assigned at creation. An owner with no householdId counts only as itself.
117	     */
118	    protected long householdSize(Owner owner) {
119	        String householdId = owner.getHouseholdId();
120	        if (householdId == null) {
121	            return 1;
122	        }
123	        long count = 0;
124	        for (Owner existing : ownerRepository.findAll()) {
125	            if (householdId.equals(existing.getHouseholdId())) {
126	                count++;
127	            }
128	        }
129	        return count;
130	    }
131	
132	    /**
133	     * Derive the owner's preferred contact channel: {@code EMAIL} when an email is present,
134	     * otherwise {@code PHONE}.
