136	    protected String contactPreference(Owner owner) {
137	        return (owner.getEmail() != null && !owner.getEmail().isEmpty()) ? "EMAIL" : "PHONE";
138	    }
139	
140	    /**
141	     * Derive the owner's age band from {@code birthDate} as at {@code registrationDate}:
142	     * {@code MINOR} when under 18, {@code ADULT} from 18 to 64, {@code SENIOR} at 65 or over.
143	     * Returns {@code null} when no birth date was supplied.
144	     */
145	    protected String ageBand(Owner owner) {
146	        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
147	            return null;
148	        }
149	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
150	        if (age < 18) {
151	            return "MINOR";
152	        }
153	        if (age < 65) {
154	            return "ADULT";
155	        }
156	        return "SENIOR";
157	    }
158	
159	    /**
160	     * Known country codes (digits after the {@code '+'}), longest first so {@code '61'} is
161	     * matched before {@code '1'}, mirroring {@code NormalizeOwnerTelephone}.
162	     */
163	    private static final String[] COUNTRY_CODES = {"61", "1"};
164	
165	    /**
166	     * Format the stored E.164 telephone for humans: the country code, a space, then the national
167	     * digits grouped in threes from the left (e.g. {@code +61412345678} -> {@code +61 412 345 678}).
168	     * Returns the raw value unchanged when it is not a recognised E.164 number.
169	     */
170	    protected String telephoneDisplay(Owner owner) {
171	        String telephone = owner.getTelephone();
172	        if (telephone == null || !telephone.startsWith("+")) {
173	            return telephone;
174	        }
175	        String digits = telephone.substring(1);
176	        String code = null;
177	        for (String candidate : COUNTRY_CODES) {
178	            if (digits.startsWith(candidate)) {
179	                code = candidate;
180	                break;
181	            }
182	        }
183	        if (code == null) {
184	            return telephone;
185	        }
186	        String national = digits.substring(code.length());
187	        StringBuilder grouped = new StringBuilder("+").append(code);
188	        for (int i = 0; i < national.length(); i += 3) {
189	            grouped.append(' ').append(national, i, Math.min(i + 3, national.length()));
190	        }
191	        return grouped.toString();
192	    }
193	
194	    /**
195	     * Compute a single Luhn check digit (0-9) over the digits contained in the owner's
196	     * {@code customerCode}. Non-digit characters (such as the hyphen separators) are ignored.
197	     */
198	    protected Integer checkDigit(Owner owner) {
199	        String code = owner.getCustomerCode();
200	        if (code == null) {
201	            return null;
202	        }
203	        int sum = 0;
204	        boolean dbl = true;
205	        for (int i = code.length() - 1; i >= 0; i--) {
206	            char c = code.charAt(i);
207	            if (c < '0' || c > '9') {
208	                continue;
209	            }
210	            int d = c - '0';
211	            if (dbl) {
212	                d *= 2;
213	                if (d > 9) {
214	                    d -= 9;
215	                }
216	            }
217	            sum += d;
218	            dbl = !dbl;
219	        }
220	        return (10 - (sum % 10)) % 10;
221	    }
222	}
