10	/**
11	 * Validates the owner's postcode WHEN PRESENT, reading the published request body. An absent or
12	 * blank postcode is accepted (the field is optional). When supplied it must be exactly four digits;
13	 * if the city has a known region ({@link Localities}), the code must also fall inside that region's
14	 * inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region
15	 * accepts any 4-digit postcode. Anything else is rejected with 400 via
16	 * {@link InvalidPostcodeException}.
17	 */
18	public class ValidateOwnerPostcode {
19	
20	    /** Region -> inclusive 4-digit postcode range {low, high}. */
21	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
22	            "NSW", new int[] {2000, 2099},
23	            "VIC", new int[] {3000, 3099},
24	            "QLD", new int[] {4000, 4099});
25	
26	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
27	        String postcode = request.getPostcode();
28	        if (postcode == null || postcode.isBlank()) {
29	            return; // optional when absent
30	        }
31	        if (!postcode.matches("[0-9]{4}")) {
32	            throw new InvalidPostcodeException(postcode);
33	        }
34	        int[] range = REGION_POSTCODES.get(Localities.of(request.getCity()));
35	        if (range == null) {
36	            return; // city with no known region accepts any 4-digit postcode
37	        }
38	        int value = Integer.parseInt(postcode);
39	        if (value < range[0] || value > range[1]) {
40	            throw new InvalidPostcodeException(postcode);
41	        }
42	    }
