1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Canonical address normalization applied whenever an owner is created. The rules are: trim the
8	 * ends, collapse every run of whitespace to a single space, upper-case, and expand a small set of
9	 * common street-type abbreviations to their full word ({@code ST -> STREET}, {@code RD -> ROAD},
10	 * {@code AVE -> AVENUE}). The result is what gets stored and returned, so equal addresses written
11	 * differently collapse to the same value.
12	 */
13	final class OwnerAddressNormalizer {
14	
15	    private static final Map<String, String> ABBREVIATIONS = Map.of(
16	            "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
17	
18	    private OwnerAddressNormalizer() {
19	    }
20	
21	    /** Normalize an address; a null or whitespace-only value normalizes to the empty string. */
22	    static String normalize(String value) {
23	        if (value == null) {
24	            return "";
25	        }
26	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
27	        if (collapsed.isEmpty()) {
28	            return "";
29	        }
30	        String[] tokens = collapsed.split(" ");
31	        StringBuilder sb = new StringBuilder(collapsed.length());
32	        for (int i = 0; i < tokens.length; i++) {
33	            if (i > 0) {
34	                sb.append(' ');
35	            }
36	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
37	        }
38	        return sb.toString();
39	    }
40	}
