2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's locality (canonical region). The postcode is preferred: the region is looked
7	 * up by postcode range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), and only when the
8	 * postcode is absent or falls in no known range does it fall back to the fixed city-to-region
9	 * table. Anything unresolved maps to {@link #UNKNOWN}.
10	 *
11	 * <p>{@link #ofPostcode(String)} resolves the region from the postcode alone — the {@code REGION}
12	 * segment of an owner's {@code customerCode} — and {@link #regionOf(String)} reads that segment
13	 * back out of a stored {@code customerCode}.
14	 */
15	public final class Localities {
16	
17	    /** Value returned when neither the postcode nor the city resolves a region. */
18	    public static final String UNKNOWN = "UNKNOWN";
19	
20	    /** City -> canonical region. */
21	    private static final Map<String, String> CITY_REGION = Map.of(
22	            "Sydney", "NSW",
23	            "Melbourne", "VIC",
24	            "Brisbane", "QLD");
25	
26	    /** Region -> inclusive 4-digit postcode range {low, high}. */
27	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
28	            "NSW", new int[] {2000, 2099},
29	            "VIC", new int[] {3000, 3099},
30	            "QLD", new int[] {4000, 4099});
31	
32	    /** Region -> IANA timezone name. */
33	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
34	            "NSW", "Australia/Sydney",
35	            "VIC", "Australia/Melbourne",
36	            "QLD", "Australia/Brisbane");
37	
38	    private Localities() {
39	    }
40	
41	    /**
42	     * The canonical region for {@code city} using only the city-to-region table, or
43	     * {@code UNKNOWN} when not in the table.
44	     */
45	    public static String of(String city) {
46	        return city == null ? UNKNOWN : CITY_REGION.getOrDefault(city, UNKNOWN);
47	    }
48	
49	    /**
50	     * The canonical region, preferring the postcode: resolves by postcode range first and only
51	     * falls back to the city-to-region table when the postcode is absent or in no known range.
52	     * Returns {@code UNKNOWN} when neither resolves.
53	     */
54	    public static String of(String city, String postcode) {
55	        String byPostcode = byPostcode(postcode);
56	        return byPostcode != null ? byPostcode : of(city);
57	    }
58	
59	    /**
60	     * The canonical region derived from the postcode ALONE (no city fallback): the region whose
61	     * range contains {@code postcode}, or {@code UNKNOWN} when the postcode is absent or in no known
62	     * range. This is the {@code REGION} segment of an owner's {@code customerCode}.
63	     */
64	    public static String ofPostcode(String postcode) {
65	        String byPostcode = byPostcode(postcode);
66	        return byPostcode != null ? byPostcode : UNKNOWN;
67	    }
68	
69	    /**
70	     * The region an owner belongs to, read back from the {@code REGION} segment of its
71	     * {@code customerCode} ({@code <REGION>-<HASH8>}) — the single region-and-hash identity all
72	     * region-derived values now flow from. Returns {@code UNKNOWN} when the code is absent or
73	     * unsegmented.
74	     */
75	    public static String regionOf(String customerCode) {
76	        if (customerCode == null) {
77	            return UNKNOWN;
78	        }
79	        int dash = customerCode.indexOf('-');
80	        return dash < 0 ? UNKNOWN : customerCode.substring(0, dash);
81	    }
82	
83	    /**
84	     * The IANA timezone name for an owner, derived from the {@code REGION} segment of its
85	     * {@code customerCode} via the fixed region-to-timezone table (NSW -> Australia/Sydney,
86	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane). Returns {@code UNKNOWN} when the
87	     * region is absent or not in the table.
88	     */
89	    public static String timezoneOf(String customerCode) {
90	        return REGION_TIMEZONE.getOrDefault(regionOf(customerCode), UNKNOWN);
91	    }
92	
93	    /** The region whose range contains {@code postcode}, or {@code null} when none does. */
94	    private static String byPostcode(String postcode) {
95	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
96	            return null;
97	        }
98	        int value = Integer.parseInt(postcode);
99	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
100	            int[] range = entry.getValue();
101	            if (value >= range[0] && value <= range[1]) {
102	                return entry.getKey();
103	            }
104	        }
105	        return null;
106	    }
107	}
