26	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
27	            throws DuplicateIdentityException {
28	        String householdId = OwnerHousehold.householdId(request);
29	        String identityKey = OwnerIdentityKey.of(request.getTelephone(), request.getEmail(), householdId);
30	        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
31	        for (Owner existing : ownerRepository.findAll()) {
32	            if (identityKey.equals(OwnerIdentityKey.of(existing))) {
33	                throw new DuplicateIdentityException(identityKey);
34	            }
35	            if (!sharesHousehold && householdId.equals(OwnerHousehold.householdId(existing))) {
36	                throw new DuplicateIdentityException(identityKey);
37	            }
38	        }
39	    }
40	}
